import{_ as o,o as c,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Spec: worker edit video chạy Claude CLI trong container","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-edit-claude-container/spec.md","filePath":"feature/video-edit-claude-container/spec.md"}'),a={name:"feature/video-edit-claude-container/spec.md"};function t(d,e,r,l,h,s){return c(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="spec-worker-edit-video-chay-claude-cli-trong-container" tabindex="-1">Spec: worker edit video chạy Claude CLI trong container <a class="header-anchor" href="#spec-worker-edit-video-chay-claude-cli-trong-container" aria-label="Permalink to &quot;Spec: worker edit video chạy Claude CLI trong container&quot;">​</a></h1><h2 id="boi-canh" tabindex="-1">Bối cảnh <a class="header-anchor" href="#boi-canh" aria-label="Permalink to &quot;Bối cảnh&quot;">​</a></h2><p>Owner là người duy nhất dùng web, làm cho nhiều khách. Edit video hiện chạy <code>claude -p</code> trong workspace <code>F:/self/DemoVideo</code> trên máy owner (<code>server_video_edit/claude_code.py</code>), nên chỉ hoạt động khi máy owner bật. Mục tiêu: đóng gói worker vào một container riêng. Tuấn sẽ dựng EC2 riêng để chạy container này sau.</p><h2 id="pham-vi" tabindex="-1">Phạm vi <a class="header-anchor" href="#pham-vi" aria-label="Permalink to &quot;Phạm vi&quot;">​</a></h2><ul><li>Image <code>Dockerfile.video-edit</code> chứa: Claude CLI 2.1.287, Node 22 (HyperFrames ≥ 22), ffmpeg, Chrome headless của HyperFrames, workspace DemoVideo (phần mã/tài liệu và bản mẫu chất lượng <code>projects/TalkingHead/edits/revision-02</code>), cùng các skill <code>fk-*</code> và bộ skill HyperFrames. MCP EditAtlas khai báo ở user scope.</li><li>Đăng nhập bằng <code>CLAUDE_CODE_OAUTH_TOKEN</code> của owner, cùng token với ai-service.</li><li>Không đổi API: worker vẫn là HTTP service ở cổng 8094, business gọi qua <code>VIDEO_EDIT_RUNTIME_URL</code>.</li><li>Không làm: dựng EC2 hay CI/CD (Tuấn làm), sửa luồng edit hoặc prompt.</li></ul><h2 id="yeu-cau" tabindex="-1">Yêu cầu <a class="header-anchor" href="#yeu-cau" aria-label="Permalink to &quot;Yêu cầu&quot;">​</a></h2><ul><li>R1: Không đưa secret vào image. DemoVideo <code>.env</code>, <code>.runtime/flow/chrome_profile</code>, <code>~/.claude/.credentials.json</code> và token đều không được copy. Script staging chỉ copy danh sách cho phép và dừng nếu phát hiện mẫu secret.</li><li>R2: <code>video-env.cmd</code> trong container là bản bash tương đương bản Windows, để lệnh trong docs và allowlist (<code>./video-env.cmd ...</code>) chạy được.</li><li>R3: Session Claude (<code>--resume</code>) và scratch giữ qua restart (named volume). Root filesystem giữ read-only.</li><li>R4: Bỏ package chỉ chạy trên Windows (<code>comtypes</code>, <code>uiautomation</code>) khi cài lock Python của DemoVideo.</li><li>R5: Tắt auto-update của CLI trong container; muốn nâng phiên bản thì build lại image.</li><li>R6: Chạy local trên Docker Desktop: business là <code>host.docker.internal:8081</code>, Mongo Atlas giữ nguyên.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Workspace dựng sẵn không chứa <code>projects/</code> của các khách (5 GB). Chỉ có bản mẫu chất lượng. Các dự án khác mount vào nếu cần.</li><li>RAM: Chrome + ffmpeg + Claude + whisper. Mặc định <code>mem_limit</code> 6g.</li></ul><h2 id="bo-sung-sau-khi-test-17-18-11" tabindex="-1">Bổ sung sau khi test (17-18/11) <a class="header-anchor" href="#bo-sung-sau-khi-test-17-18-11" aria-label="Permalink to &quot;Bổ sung sau khi test (17-18/11)&quot;">​</a></h2><ul><li>R7: Container dùng database Mongo riêng (<code>VIDEO_EDIT_MONGO_DATABASE=brandhub_owner_edit</code>). Journal chỉ có một lease executor toàn cục, nên các worker dùng chung một DB sẽ giành job của nhau. Đã thấy job bị một worker lạ trên DB <code>brandhub</code> nhận rồi báo lỗi sau 0.3 giây.</li><li>R8: Theo quyết định của owner, Claude được chạy mọi lệnh Bash trong container (managed settings <code>/etc/claude-code/managed-settings.json</code>). Container là sandbox: user thường, root filesystem chỉ đọc, chỉ ghi được scratch và cache. Allowlist trong <code>claude_code.py</code> vẫn áp dụng khi chạy trên máy owner.</li><li>R9: Nếu <code>TIMELINE.json</code> không hợp lệ, worker vẫn giao MP4 (không chỉnh được từng lớp) và ghi log lý do. Chuyển cảnh dissolve/slide dài hơn đoạn chồng clip được rút lại bằng đoạn chồng, không có đoạn chồng thì đổi thành cut.</li><li>R10: Docker Desktop: <code>VIDEO_EDIT_UPLOAD_REWRITE</code> đổi URL upload <code>localhost:8080</code> của business sang <code>host.docker.internal:8080</code>. Trên EC2 không cần.</li><li>R11: Worker ghi log loại lỗi và vị trí trong code khi job thất bại, không ghi message vì có thể lộ token.</li></ul>',11)])])}const m=o(a,[["render",t]]);export{g as __pageData,m as default};
